import { useRef, useState } from 'react'
const moods=[['😊','Радісно','Згадай щось приємне.'],['😟','Тривожно','Озирнись навколо або поклич дорослого.'],['😠','Сердито','Стисни долоні й м’яко розслаб їх.'],['😢','Сумно','Побудь поруч із тим, кому довіряєш.'],['😴','Втомлено','Можна відпочити.'],['😶','Не знаю','Це теж відповідь. Не поспішай.']]
const steps=[['🦶','Відчуй опору','Відчуй ноги на підлозі, якщо це зручно.'],['👀','Знайди три речі','Назви три речі, які бачиш.'],['👂','Послухай','Поміть один звук поруч.'],['🌱','Обери далі','Продовжити, відпочити чи покликати дорослого?']]
const cards=[['☁️','Хмаринка'],['🌙','Місяць'],['🌼','Квітка'],['🐌','Равлик']]
export default function Playroom(){
 const [mood,setMood]=useState(''),[breath,setBreath]=useState('ready'),[choice,setChoice]=useState(''),[step,setStep]=useState(-1),[story,setStory]=useState(''),[done,setDone]=useState([]),[pair,setPair]=useState(''),[matches,setMatches]=useState([]),[color,setColor]=useState('#3f7654'),[size,setSize]=useState(5),[drawing,setDrawing]=useState(false);const canvas=useRef(null)
 const complete=id=>setDone(old=>old.includes(id)?old:[...old,id])
 const start=e=>{const c=canvas.current,r=c.getBoundingClientRect(),x=c.getContext('2d');c.setPointerCapture(e.pointerId);x.beginPath();x.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);x.strokeStyle=color;x.lineWidth=size;x.lineCap='round';setDrawing(true)}
 const move=e=>{if(!drawing)return;const c=canvas.current,r=c.getBoundingClientRect(),x=c.getContext('2d');x.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);x.stroke()}
 const match=k=>{if(matches.includes(k))return;if(!pair){setPair(k);return}if(pair===k){const next=[...matches,k];setMatches(next);setPair('');if(next.length===4)complete('match')}else setPair(k)}
 return <section id="playroom" className="playroom-section"><div className="wrap"><div className="playroom-heading"><span className="playroom-kicker">🌼 ТВОЄ ТИХЕ МІСЦЕ</span><h2>Що хочеш спробувати?</h2><p>Обирай те, що підходить. Тут немає оцінок. Можна зупинитися будь-коли.</p><div className="play-progress" aria-live="polite"><span className="progress-flower">✿</span><div><strong>Спробовано активностей: {done.length} із 6</strong><div className="progress-track" role="progressbar" aria-label="Виконані активності" aria-valuemin="0" aria-valuemax="6" aria-valuenow={done.length}><span style={{width:(done.length/6*100)+'%'}}/></div></div><button className="progress-reset" onClick={()=>{setDone([]);setMood('');setBreath('ready');setChoice('');setStep(-1);setStory('');setMatches([]);setPair('')}}>Почати знову</button></div></div>
 <article className="play-card"><div className="play-card-copy"><span className="activity-number">01 · ПОЧУТТЯ</span><h3>Як ти зараз?</h3><p>Обери обличчя, схоже на твій настрій.</p><div className="feeling-choices" role="group" aria-label="Обери почуття">{moods.map(m=><button key={m[1]} className={'feeling-option '+(mood===m[1]?'selected':'')} aria-pressed={mood===m[1]} onClick={()=>{setMood(m[1]);complete('mood')}}><span>{m[0]}</span><span>{m[1]}</span></button>)}</div>{mood&&<p className="activity-feedback" role="status">{moods.find(m=>m[1]===mood)[2]} <button className="inline-activity-link" onClick={()=>setMood('')}>Обрати інше</button></p>}</div><div className="feeling-art"><span>{(moods.find(m=>m[1]===mood)||['🌈'])[0]}</span><p>Усі почуття можна відчувати.</p></div></article>
 <article className="play-card"><div className="play-card-copy"><span className="activity-number">02 · ДИХАННЯ</span><h3>Допоможи хмаринці плисти ☁️</h3><p>Дивись на хмаринку й дихай як зручно. Не треба набирати багато повітря.</p><div className="breathing-controls"><button className="play-button" onClick={()=>{setBreath(b=>b==='running'?'paused':'running');if(breath==='running')complete('breath')}}>{breath==='running'?'Пауза':breath==='paused'?'Продовжити':'Почнімо разом'}</button><button className="soft-button" onClick={()=>{setBreath('ready');complete('breath')}}>Завершити</button><button className="soft-button" onClick={()=>setBreath('running')}>Ще раз</button></div><p className="activity-feedback" role="status">{breath==='running'?'Хмаринка рухається. Ти керуєш темпом.':breath==='paused'?'Пауза. Можна відпочити.':'Почни, коли будеш готовий/готова.'}</p></div><div className="cloud-stage"><div className={'cloud-buddy '+(breath==='running'?'cloud-moving':'')}><span>☁️</span><i>•ᴗ•</i></div><span className="cloud-ground">тихо-тихо</span></div></article>
 <article className="play-card"><div className="play-card-copy"><span className="activity-number">03 · ВИБІР</span><h3>Що може допомогти?</h3><p>У кімнаті шумно, і тобі важко. Що можна зробити?</p><div className="scenario-options">{[['pause','🫶','Попросити паузу'],['quiet','🌿','Знайти тихіше місце'],['adult','🤝','Сказати дорослому']].map(x=><button key={x[0]} className={'scenario-option '+(choice===x[0]?'selected':'')} aria-pressed={choice===x[0]} onClick={()=>{setChoice(x[0]);complete('choice')}}><span>{x[1]}</span>{x[2]}</button>)}</div>{choice&&<p className="activity-feedback" role="status">Це спосіб подбати про себе. Твій вибір має значення. Можна обрати інше.</p>}</div></article>
 <article className="play-card"><div className="play-card-copy"><span className="activity-number">04 · ПАУЗА ДЛЯ СЕБЕ</span><h3>Поміть світ навколо</h3><p>Обери крок. Будь-який крок можна пропустити.</p><div className="grounding-steps">{steps.map((s,i)=><button key={s[1]} className={'ground-step '+(step===i?'selected':'')} onClick={()=>{setStep(i);if(i===3)complete('ground')}}><span className="ground-icon">{s[0]}</span><span><strong>{i+1}. {s[1]}</strong><small>{s[2]}</small></span><span>→</span></button>)}</div>{step>=0&&<p className="activity-feedback" role="status">{steps[step][2]} {step<3?<button className="inline-activity-link" onClick={()=>setStep(step+1)}>Наступний крок →</button>:<button className="inline-activity-link" onClick={()=>{setStep(-1);complete('ground')}}>Почати знову</button>}</p>}</div></article>
 <article className="play-card art-card"><div className="play-card-copy"><span className="activity-number">05 · ТВОРЧІСТЬ</span><h3>Намалюй свій настрій</h3><p>Малюй пальцем або мишкою. Тут не буває неправильних малюнків.</p><div className="art-tools"><label>Колір <select value={color} onChange={e=>setColor(e.target.value)}><option value="#3f7654">Зелений</option><option value="#e18b70">Персиковий</option><option value="#8a77b5">Бузковий</option><option value="#d2a43e">Жовтий</option><option value="#345d85">Синій</option></select></label><label>Пензлик <input aria-label="Розмір пензлика" type="range" min="2" max="18" value={size} onChange={e=>setSize(Number(e.target.value))}/></label><button className="soft-button" onClick={()=>canvas.current.getContext('2d').clearRect(0,0,canvas.current.width,canvas.current.height)}>Очистити</button></div><canvas ref={canvas} width="720" height="280" className="drawing-canvas" aria-label="Полотно для малювання: проведи пальцем або мишкою" style={{touchAction:'none'}} onPointerDown={start} onPointerMove={move} onPointerUp={()=>{setDrawing(false);complete('art')}} onPointerCancel={()=>setDrawing(false)} onPointerLeave={()=>setDrawing(false)}/><button className="soft-button" onClick={()=>complete('art')}>Я закінчив/закінчила</button></div></article>
 <article className="play-card"><div className="play-card-copy"><span className="activity-number">06 · ІСТОРІЯ</span><h3>Куди піде равлик? 🐌</h3><p>Равлик шукає затишне місце. Обери, куди йому піти.</p><div className="story-scene"><span>☀️</span><span>🐌</span><span>🌼</span><span>🍄</span></div><div className="scenario-options"><button className="scenario-option" onClick={()=>{setStory('Під квіткою пахне літом. Равлик відпочив і пішов далі, коли був готовий.');complete('story')}}>🌼 Під квітку</button><button className="scenario-option" onClick={()=>{setStory('Під грибочком сухо й затишно. Равлик відпочив і пішов далі, коли був готовий.');complete('story')}}>🍄 До грибочка</button></div>{story&&<p className="activity-feedback" role="status">{story} <button className="inline-activity-link" onClick={()=>setStory('')}>Інший шлях</button></p>}</div></article>
 <article className="play-card matching-card"><div className="play-card-copy"><span className="activity-number">07 · ЗНАЙДИ ПАРУ</span><h3>Картинки-друзі</h3><p>Обери картинку, а потім назву до неї.</p><div className="matching-grid">{cards.map(c=><button key={'i'+c[1]} className={'match-tile '+(matches.includes(c[1])?'matched':pair===c[1]?'selected':'')} aria-pressed={matches.includes(c[1])||pair===c[1]} onClick={()=>match(c[1])}>{c[0]}</button>)}{cards.map(c=><button key={'t'+c[1]} className={'match-tile '+(matches.includes(c[1])?'matched':pair===c[1]?'selected':'')} aria-pressed={matches.includes(c[1])||pair===c[1]} onClick={()=>match(c[1])}>{c[1]}</button>)}</div><p className="activity-feedback" role="status">{matches.length===4?'Усі пари знайшлися! Чудово!':pair?'Тепер обери назву до картинки.':'Знайдено пар: '+matches.length+' із 4.'}</p><button className="soft-button" onClick={()=>{setMatches([]);setPair('')}}>Грати ще раз</button></div></article><p className="playroom-note">Ці вправи допомагають зробити паузу, але не замінюють підтримку дорослого, якому ти довіряєш.</p></div></section>
}
